// Emparelha o evento criado (id) com o agendamento original (a.id) por índice.
const pendentes = $('Buscar Agendamentos Pendentes').all().map(i => i.json);
const eventos = $input.all().map(i => i.json);
return eventos.map((ev, idx) => ({ json: { appointment_id: pendentes[idx] ? pendentes[idx].id : null, event_id: ev.id } }));
